    ScreenshotEvent,
    where=lambda e: e.url == url,
    past=False,    # skip history
    future=2,      # wait up to 2s for another caller to emit
)

event = in_flight or bus.emit(ScreenshotEvent(url=url))
await event.now()
result = await event.event_result()
```

