## Pattern 4: Keyed helper for repeated use

Wrap the debounce logic once and reuse it for all expensive keyed actions.

<Tabs>
<Tab title="Python">

```python
async def emit_debounced_screenshot(url: str):
    event = (
        await bus.find(ScreenshotEvent, where=lambda e: e.url == url, past=15, future=False)
        or await bus.find(ScreenshotEvent, where=lambda e: e.url == url, past=False, future=3)
        or bus.emit(ScreenshotEvent(url=url))
    )
    await event.now()
    return await event.event_result()
```

</Tab>
<Tab title="TypeScript">

```ts
const emitDebouncedScreenshot = async (url: string) => {
  const event =
    (await bus.find(ScreenshotEvent, (e) => e.url === url, { past: 15, future: false })) ??
    (await bus.find(ScreenshotEvent, (e) => e.url === url, { past: false, future: 3 })) ??
    bus.emit(ScreenshotEvent({ url }))

  await event.now()
  return await event.eventResult()
}
```

</Tab>
<Tab title="Rust">

```rust
fn emit_debounced_screenshot(bus: &EventBus, url: &str) -> Result<Option<serde_json::Value>, String> {
    let by_url = HashMap::from([("url".to_string(), json!(url))]);
    let event = block_on(bus.find_with_options(
        ScreenshotEvent::event_type,
        FindOptions {
            past_window: Some(15.0),
            future: None,
            where_filter: Some(by_url.clone()),
            ..FindOptions::default()
        },
    ))
    .or_else(|| {
        block_on(bus.find_with_options(
            ScreenshotEvent::event_type,
            FindOptions {
                past: false,
                future: Some(3.0),
                where_filter: Some(by_url),
                ..FindOptions::default()
            },
        ))
    })
    .unwrap_or_else(|| {
        bus.emit(ScreenshotEvent { url: url.to_string(), ..Default::default() })
    });

    block_on(event.now());
    block_on(event.event_result())
}
```

</Tab>
<Tab title="Go">

```go
func emitDebouncedScreenshot(ctx context.Context, bus *abxbus.EventBus, url string) (any, error) {
	sameURL := func(event *abxbus.BaseEvent) bool {
		return event.Payload["url"] == url
	}

	event, err := bus.FindEventName("ScreenshotEvent", sameURL, &abxbus.FindOptions{Past: 15.0, Future: false})
	if err != nil {
		return nil, err
	}
	if event == nil {
		event, err = bus.FindEventName("ScreenshotEvent", sameURL, &abxbus.FindOptions{Past: false, Future: 3.0})
		if err != nil {
			return nil, err
		}
	}
	if event == nil {
		event = bus.Emit(abxbus.NewBaseEvent("ScreenshotEvent", map[string]any{"url": url}))
	}

	if _, err := event.Now(); err != nil {
		return nil, err
	}
	return event.EventResult()
}
```

</Tab>
</Tabs>

## Important behavior notes

- `find(...)` resolves when an event is emitted, not when handlers finish.
- Always await completion after selecting a debounced event:
  - Python: `await event.now()`, then `await event.event_result()`
  - TypeScript: `await event.now()`, then `await event.eventResult()`
  - Go: `event.Now()`, then `event.EventResult()`
- Debouncing scope depends on your match key (`where` / event-field filters).  
  Use the narrowest key that represents "same work."
- Debouncing depends on retained history. If history is aggressively trimmed, your `past` window can become less effective.

See also:

- [Find Events](./find-events)
- [Event History Store](./event-history-store)

const fs = require('fs')
const http = require('http')
const path = require('path')
const { test, expect } = require('playwright/test')

test.describe('browser runtime perf', () => {
  test.setTimeout(120_000)

  test('runs shared perf scenarios in Chromium JS runtime', async ({ page, browserName }) => {
    expect(browserName).toBe('chromium')

    const rootDir = path.resolve(__dirname, '..')
    const server = http.createServer((req, res) => {
      const requestUrl = new URL(req.url || '/', 'http://127.0.0.1')
      const pathname = decodeURIComponent(requestUrl.pathname)

      if (pathname === '/' || pathname === '/index.html') {
        res.statusCode = 200
        res.setHeader('content-type', 'text/html; charset=utf-8')
        res.end(`<!doctype html>
<html>
  <head>
    <meta charset="utf-8" />
    <script type="importmap">
      {
        "imports": {
          "uuid": "/node_modules/uuid/dist/esm-browser/index.js",
          "zod": "/node_modules/zod/index.js"
        }
      }
    </script>
  </head>
  <body>browser perf harness</body>
</html>`)
        return
      }

      const absolutePath = path.resolve(rootDir, `.${pathname}`)
      const relativePath = path.relative(rootDir, absolutePath)
      if (relativePath.startsWith('..') || path.isAbsolute(relativePath)) {
        res.statusCode = 403
        res.end('forbidden')
        return
      }
      if (!fs.existsSync(absolutePath) || fs.statSync(absolutePath).isDirectory()) {
        res.statusCode = 404
        res.end('not found')
        return
      }

      const ext = path.extname(absolutePath)
      if (ext === '.js' || ext === '.mjs' || ext === '.cjs') {
        res.setHeader('content-type', 'text/javascript; charset=utf-8')
      } else if (ext === '.map' || ext === '.json') {
        res.setHeader('content-type', 'application/json; charset=utf-8')
      } else if (ext === '.html') {
        res.setHeader('content-type', 'text/html; charset=utf-8')
      } else {
        res.setHeader('content-type', 'text/plain; charset=utf-8')
      }

      res.statusCode = 200
      res.end(fs.readFileSync(absolutePath))
    })

    await new Promise((resolve, reject) => {
      server.once('error', reject)
      server.listen(0, '127.0.0.1', () => {
        server.removeListener('error', reject)
        resolve()
      })
    })

    const address = server.address()
    if (!address || typeof address === 'string') {
      await new Promise((resolve) => server.close(() => resolve()))
      throw new Error('failed to resolve browser perf server address')
    }
    const baseUrl = `http://127.0.0.1:${address.port}`

    let result
    try {
      await page.goto(`${baseUrl}/`)
      result = await page.evaluate(async () => {
        const [api, scenarios] = await Promise.all([import('/dist/esm/index.js'), import('/tests/performance.scenarios.js')])
        const logs = []

        const results = await scenarios.runAllPerfScenarios({
          runtimeName: 'chromium-js',
          api: {
            BaseEvent: api.BaseEvent,
            EventBus: api.EventBus,
            EventHandlerTimeoutError: api.EventHandlerTimeoutError,
            EventHandlerCancelledError: api.EventHandlerCancelledError,
          },
          now: () => performance.now(),
          sleep: (ms) => new Promise((resolve) => setTimeout(resolve, ms)),
          log: (message) => logs.push(message),
          limits: {
            singleRunMs: 30_000,
            worstCaseMs: 60_000,
          },
        })

        return { logs, results }
      })
    } finally {
      await new Promise((resolve) => server.close(() => resolve()))
    }

    for (const line of result.logs) {
      console.log(line)
    }

    expect(result.results.length).toBe(6)
  })
})
